public class VarargsMathTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("sum(1, 2, 3)", 6, VarargsMath.sum(1, 2, 3));
        check("sum()", 0, VarargsMath.sum());
        check("sum(10)", 10, VarargsMath.sum(10));
        check("sum(-5, 5, 7)", 7, VarargsMath.sum(-5, 5, 7));
        check("max(3, 9, 2)", 9, VarargsMath.max(3, 9, 2));
        check("max()", Integer.MIN_VALUE, VarargsMath.max());
        check("max(-3, -7)", -3, VarargsMath.max(-3, -7));
        check("max(42)", 42, VarargsMath.max(42));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

