public class VarargsMath {

    public static int sum(int... values) {
        int total = 0;
        for (int v : values) {
            total += v;
        }
        return total;
    }

    public static int max(int... values) {
        int largest = Integer.MIN_VALUE;
        for (int v : values) {
            if (v > largest) {
                largest = v;
            }
        }
        return largest;
    }
}
